def filter_api_calls(
    logp_with_result: np.ndarray,
    logp_call_only: np.ndarray,
    logp_no_call: np.ndarray,
    tau_filter: float,
) -> tuple[np.ndarray, np.ndarray]:
    """Return an ordered keep mask and one finite margin per proposed call."""
    for mat in [logp_with_result, logp_call_only, logp_no_call]:
        if not isinstance(mat, np.ndarray):
            raise ValueError("Input must be numpy array")
        if mat.ndim != 2:
            raise ValueError("Input must be 2D matrix")
        if mat.size == 0:
            raise ValueError("Input must not be empty")
        if not np.all(np.isfinite(mat)):
            raise ValueError("Input contains nonfinite values")
        if np.any(mat > 0):
            raise ValueError("Input contains positive values")
    if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
        raise ValueError("Shape mismatch")
    if isinstance(tau_filter, bool):
        raise ValueError("tau_filter cannot be a boolean")
    if not np.isfinite(tau_filter) or tau_filter < 0:
        raise ValueError("tau_filter must be a finite nonnegative float")

    future_horizon = logp_with_result.shape[1]
    t = np.arange(future_horizon)
    raw_weights = np.maximum(0, 1 - 0.2 * t)
    weights = raw_weights / raw_weights.sum()

    L_plus = -np.sum(logp_with_result * weights, axis=1)
    L_call_only = -np.sum(logp_call_only * weights, axis=1)
    L_empty = -np.sum(logp_no_call * weights, axis=1)

    L_minus = np.minimum(L_empty, L_call_only)
    margin = L_minus - L_plus
    keep = margin >= tau_filter

    return keep, margin
